use crate::meta::ctstring::AsCtString;
use crate::meta::derive_via;

/// Compare two values for equality
///
/// `Eq` provides the `==` and `!=` operators. It is implemented for [`Field`], the integer types,
/// `bool`, `str`, arrays, vectors and tuples of `Eq` types, and can be derived with
/// `#[derive(Eq)]`, which compares every field of a struct.
///
/// Example:
///
/// ```noir
/// #[derive(Eq)]
/// struct Point {
///     x: Field,
///     y: Field,
/// }
///
/// fn main() {
///     assert(Point { x: 1, y: 2 } == Point { x: 1, y: 2 });
///     assert(Point { x: 1, y: 2 } != Point { x: 2, y: 1 });
/// }
/// ```
#[derive_via(derive_eq)]
// docs:start:eq-trait
pub trait Eq {
    /// Returns `true` if `self` and `other` are equal. `a == b` calls `a.eq(b)`.
    fn eq(self, other: Self) -> bool;
}
// docs:end:eq-trait

// docs:start:derive_eq
comptime fn derive_eq(s: TypeDefinition) -> Quoted {
    let signature = quote { fn eq(_self: Self, _other: Self) -> bool };
    let for_each_field = |name| quote { (_self.$name == _other.$name) };
    let body = |fields| {
        if s.fields_as_written().len() == 0 {
            quote { true }
        } else {
            fields
        }
    };
    crate::meta::make_trait_impl(
        s,
        quote { $crate::cmp::Eq },
        signature,
        for_each_field,
        quote { & },
        body,
    )
}
// docs:end:derive_eq

impl Eq for Field {
    fn eq(self, other: Field) -> bool {
        self == other
    }
}

impl Eq for u128 {
    fn eq(self, other: u128) -> bool {
        self == other
    }
}
impl Eq for u64 {
    fn eq(self, other: u64) -> bool {
        self == other
    }
}
impl Eq for u32 {
    fn eq(self, other: u32) -> bool {
        self == other
    }
}
impl Eq for u16 {
    fn eq(self, other: u16) -> bool {
        self == other
    }
}
impl Eq for u8 {
    fn eq(self, other: u8) -> bool {
        self == other
    }
}
impl Eq for i8 {
    fn eq(self, other: i8) -> bool {
        self == other
    }
}
impl Eq for i16 {
    fn eq(self, other: i16) -> bool {
        self == other
    }
}
impl Eq for i32 {
    fn eq(self, other: i32) -> bool {
        self == other
    }
}
impl Eq for i64 {
    fn eq(self, other: i64) -> bool {
        self == other
    }
}

impl Eq for () {
    fn eq(_self: Self, _other: ()) -> bool {
        true
    }
}
impl Eq for bool {
    fn eq(self, other: bool) -> bool {
        self == other
    }
}

impl<T, let N: u32> Eq for [T; N]
where
    T: Eq,
{
    fn eq(self, other: [T; N]) -> bool {
        let mut result = true;
        for i in 0..self.len() {
            result &= self[i].eq(other[i]);
        }
        result
    }
}

impl<T> Eq for [T]
where
    T: Eq,
{
    fn eq(self, other: [T]) -> bool {
        let mut result = self.len() == other.len();
        if result {
            for i in 0..self.len() {
                result &= self[i].eq(other[i]);
            }
        }
        result
    }
}

impl<let N: u32> Eq for str<N> {
    fn eq(self, other: str<N>) -> bool {
        let self_bytes = self.as_bytes();
        let other_bytes = other.as_bytes();
        self_bytes == other_bytes
    }
}

comptime fn make_tuple_eq_body(n: u32) -> Quoted {
    let mut body = f"self.0.eq(other.0)".as_ctstring();
    for i in 1u32..n {
        body = body.append_fmtstr(f" & self.{i}.eq(other.{i})");
    }
    f"{body}".quoted_contents()
}

impl<A: Eq> Eq for (A,) {
